package dev.matchlab;import java.util.*;
public final class RunComparator {public record Delta(double pathError,double imbalance,double reliability,String verdict){}public Delta compare(TelemetryAnalyzer.Report baseline,TelemetryAnalyzer.Report candidate){double path=candidate.rmsPathError()-baseline.rmsPathError(),motor=candidate.motorImbalance()-baseline.motorImbalance(),reliability=candidate.reliability()-baseline.reliability();String verdict=reliability<-.05||path>.1||motor>.1?"regression":reliability>.05||path<-.1||motor<-.1?"improvement":"similar";return new Delta(path,motor,reliability,verdict);}}
